async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
  const tool = this.tools.get(name);
  if (!tool) {
    log.warn('tool', 'tool not found', {name});
    throw new Error(`Unknown tool: ${name}`);
  }

  const definition = this.resolveDefinition(tool.definitionSource);
  let validate = this.validatorCache.get(definition.inputSchema);
  if (!validate) {
    validate = this.ajv.compile(definition.inputSchema);
    this.validatorCache.set(definition.inputSchema, validate);
  }

  if (!validate(input)) {
    const errors = validate.errors ?? [];
    const message = errors
      .map(e => {
        const path = e.instancePath || 'input';
        if (e.keyword === 'required') {
          return `property ${e.params.missingProperty} is required`;
        }
        return `property ${path} ${e.message}`;
      })
      .join(', ');

    log.warn('tool', 'validation failed', {name, errors: message});
    return {result: `Validation failed: ${message}`};
  }

  log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
  const rawResult = await tool.execute(input, context);
  const response = normalizeToolResponse(rawResult);

